#include <stdio.h>
#include <string.h>

struct Reading {
    char sensor;
    int value;
    short flags;
};

void dump(const void *data, size_t size) {
    const unsigned char *bytes = data;
    for (size_t i = 0; i < size; i++) {
        printf(i + 1 < size ? "%02x " : "%02x\n", bytes[i]);
    }
}

int main(void) {
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        char sensor;
        int value, flags;
        scanf(" %c %d %d", &sensor, &value, &flags);
        struct Reading r;
        r.sensor = sensor;
        r.value = value;
        r.flags = (short)flags;
        dump(&r, sizeof r);
    }
    return 0;
}

